<p>Utils.py</p>
<pre><code>def get_endpoint(payload):
   value = payload[&quot;value&quot;]
   if value != &quot;&quot;:
       if value == &quot;back&quot;:
           url = reverse(&quot;app-previous-dialog&quot;)
       elif value == &quot;abort&quot;:
           url = reverse(&quot;app-abort&quot;)
       else:
           url = reverse(&quot;app-next-dialog&quot;)
   elif value == &quot;&quot;:
       url = reverse(&quot;app-start-assessment&quot;)
   return url

def encodeurl(payload, url):
   qs = &quot;?&quot; + urlencode(payload, safe=&quot;&quot;)
   reverse_url = url + qs
   return reverse_url
</code></pre>
